function findAsset($dir,$prefix){
  $files=glob(__DIR__.'/'.$dir.'/'.$prefix.'.*');
  return $files ? basename($files[0]) : null;
}
function esc($s){return htmlspecialchars($s, ENT_QUOTES, 'UTF-8');}
$profile=findAsset('uploads','profile');
$videos=[]; for($i=1;$i<=14;$i++) $videos[$i]=findAsset('uploads','video_'.str_pad($i,2,'0',STR_PAD_LEFT));
$thumbs=[]; for($i=1;$i<=4;$i++) $thumbs[$i]=findAsset('uploads','thumb_'.str_pad($i,2,'0',STR_PAD_LEFT));
$posters=[]; for($i=1;$i<=5;$i++) $posters[$i]=findAsset('uploads','poster_'.str_pad($i,2,'0',STR_PAD_LEFT));
