<div class="modal" id="modal"><div class="modal-content"><button class="close" id="closeModal">×</button><div id="modalMedia"></div><div class="modal-tools" id="modalTools"></div><div class="modal-caption" id="modalCaption"></div></div></div>
<script>
const modal=document.getElementById('modal'),modalMedia=document.getElementById('modalMedia'),modalCaption=document.getElementById('modalCaption'),modalTools=document.getElementById('modalTools');
function openModal(type,url,title){modalMedia.innerHTML='';modalTools.innerHTML='';let el=document.createElement(type==='video'?'video':'img');el.src=url;if(type==='video'){el.controls=true;el.autoplay=true;el.playsInline=true;el.setAttribute('aria-label',title);modalTools.innerHTML='<button type="button" id="fsBtn">⛶ Fullscreen</button>';modalTools.querySelector('#fsBtn').onclick=()=>{if(el.requestFullscreen)el.requestFullscreen();else if(el.webkitRequestFullscreen)el.webkitRequestFullscreen();};}else el.alt=title;modalMedia.appendChild(el);modalCaption.textContent=title;modal.classList.add('open');}
function closeModal(){modal.classList.remove('open');modalMedia.innerHTML='';modalTools.innerHTML='';}
document.getElementById('closeModal').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)entry.target.classList.add('show')}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
</script></body></html>
